#!/usr/bin/env python3
"""HSG Advanced — Module 11: hsga-intervaldp (Interval DP).

Matrix chain multiplication, linear stone merging, and longest palindromic
subsequence with a heavy load; near-miss W uses a wrong split point
(greedy middle split) and a behavioral W drops the interval merge cost.

Conventions: zero literal backslashes. Test input AND want use real
newlines via T(); C++ bodies via cpp() turning {{NL}} into \n escapes.
"""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from hsga import (
    write_module, write_lesson, write_practice, write_checkpoint,
    challenge, vi_challenge, contest_test,
)

Q = chr(92)
NL = chr(10)


def cpp(s):
    return s.replace("{{NL}}", Q + "n")


def T(*lines):
    return "".join(l + NL for l in lines)


CPP_STD = cpp("""#include <iostream>
#include <algorithm>
#include <vector>
#include <string>
using namespace std;
void solve(std::istream& in, std::ostream& out) {
""")

END = "}" + NL

M = "hsga-intervaldp"

# ------------------------------------------------------------------ bodies
# A1: matrix chain multiplication. Input: n (matrix count) then n+1 dims.
# Output: min scalar multiplications.
A1_R = CPP_STD + cpp("""
    int n; in >> n;
    vector<long long> d(n + 1);
    for (auto& x : d) in >> x;
    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));
    for (int L = 2; L <= n; ++L)
        for (int i = 1; i + L - 1 <= n; ++i) {
            int j = i + L - 1;
            dp[i][j] = LLONG_MAX;
            for (int k = i; k < j; ++k)
                dp[i][j] = min(dp[i][j],
                               dp[i][k] + dp[k+1][j] + d[i-1]*d[k]*d[j]);
        }
    out << (n <= 1 ? 0LL : dp[1][n]) << "{{NL}}";
""") + END

# A1 W: greedy — always split at the position with the cheapest local cost
# (not a real DP; wrong on classic cases).
A1_W = CPP_STD + cpp("""
    int n; in >> n;
    vector<long long> d(n + 1);
    for (auto& x : d) in >> x;
    // WRONG: recursive greedy — pick the k minimizing the CURRENT merge
    // cost d[i-1]*d[k]*d[j], never revisiting. Fails on [10,30,5,60].
    auto g = [&](auto&& self, int i, int j) -> long long {
        if (j - i < 1) return 0;
        long long best = LLONG_MAX; int bk = i;
        for (int k = i; k < j; ++k) {
            long long c = d[i-1]*d[k]*d[j];
            if (c < best) { best = c; bk = k; }
        }
        return best + self(self, i, bk) + self(self, bk + 1, j);
    };
    out << (n <= 1 ? 0LL : g(g, 1, n)) << "{{NL}}";
""") + END

# A2: linear stone merging — merge adjacent piles, cost = sum of the two.
# Input: n, then n pile sizes. Output: min total cost.
A2_R = CPP_STD + cpp("""
    int n; in >> n;
    vector<long long> a(n + 1), pre(n + 1, 0);
    for (int i = 1; i <= n; ++i) { in >> a[i]; pre[i] = pre[i-1] + a[i]; }
    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));
    for (int L = 2; L <= n; ++L)
        for (int i = 1; i + L - 1 <= n; ++i) {
            int j = i + L - 1;
            dp[i][j] = LLONG_MAX;
            long long s = pre[j] - pre[i-1];
            for (int k = i; k < j; ++k)
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + s);
        }
    out << (n <= 1 ? 0LL : dp[1][n]) << "{{NL}}";
""") + END

# A2 W: greedy — always merge the two smallest ADJACENT piles.
A2_W = CPP_STD + cpp("""
    int n; in >> n;
    vector<long long> a(n);
    for (auto& x : a) in >> x;
    // WRONG: repeatedly merge the adjacent pair with the smallest sum —
    // locally cheap, globally wrong (e.g. [3,1,2,5]: merging 1,2 first is
    // optimal; greedy might pick 3,1).
    long long cost = 0;
    while ((int)a.size() > 1) {
        int bi = 0; long long bs = a[0] + a[1];
        for (int i = 1; i + 1 < (int)a.size(); ++i)
            if (a[i] + a[i+1] < bs) { bs = a[i] + a[i+1]; bi = i; }
        a[bi] = bs;
        a.erase(a.begin() + bi + 1);
        cost += bs;
    }
    out << cost << "{{NL}}";
""") + END

# A3: longest palindromic subsequence. Input: T strings? No — a single
# string per test; solve() loops until EOF for the load (multiple lines).
A3_R = CPP_STD + cpp("""
    string s;
    while (in >> s) {
        int n = s.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = n - 1; i >= 0; --i) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; ++j) {
                if (s[i] == s[j])
                    dp[i][j] = (i + 1 <= j - 1) ? dp[i+1][j-1] + 2 : 2;
                else
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1]);
            }
        }
        out << (n ? dp[0][n-1] : 0) << "{{NL}}";
    }
""") + END

# A3 W: greedy two-pointer — walk inward from both ends, matching equal
# chars, skipping one on mismatch (loses palindromes that need asymmetric
# skipping).
A3_W = CPP_STD + cpp("""
    string s;
    while (in >> s) {
        int i = 0, j = (int)s.size() - 1, len = 0;
        while (i <= j) {
            if (s[i] == s[j]) { len += (i == j) ? 1 : 2; ++i; --j; }
            else { ++i; }   // WRONG: always drop the left char
        }
        out << len << "{{NL}}";
    }
""") + END

CP_M11_R = A2_R
CP_M11_W = A2_W

